builder.Services.AddProblemDetails();
builder.Services.AddExceptionHandler<GlobalExceptionHandler>();

// --- Then in the middleware pipeline (after Build(), before Run()): ---

app.UseExceptionHandler();   // Invokes your GlobalExceptionHandler
app.UseStatusCodePages();    // Converts empty error responses to ProblemDetails too

// --- Example endpoints to demonstrate: ---

