{
    if (id < 0) throw new ArgumentException("ID must be non-negative.");
    if (id == 0) throw new KeyNotFoundException($"Item {id} not found.");
    if (id == 99) throw new InvalidOperationException("Item is in a conflicting state.");
    if (id == 100) throw new Exception("Something unexpected happened.");
    return Results.Ok(new { Id = id, Name = "Widget" });
});

